/** In-memory R2 bucket double: put/get/delete/list over a Map. */
function fakeR2Bucket() {
  const objects = new Map<string, { bytes: Uint8Array; contentType?: string; fileName?: string }>();
  const gets: string[] = [];
  return {
    objects,
    gets,
    bucket: {
      async put(key: string, value: Uint8Array | string, options?: {
        httpMetadata?: { contentType?: string };
        customMetadata?: Record<string, string>;
      }) {
        const bytes = typeof value === "string" ? new TextEncoder().encode(value) : value;
        objects.set(key, {
          bytes,
          contentType: options?.httpMetadata?.contentType,
          fileName: options?.customMetadata?.fileName,
        });
      },
      async get(key: string) {
        gets.push(key);
        const obj = objects.get(key);
        if (!obj) return null;
        return {
          async arrayBuffer() { return obj.bytes.buffer.slice(obj.bytes.byteOffset, obj.bytes.byteOffset + obj.bytes.byteLength); },
          httpMetadata: obj.contentType ? { contentType: obj.contentType } : undefined,
          customMetadata: obj.fileName ? { fileName: obj.fileName } : undefined,
        };
      },
      async delete(key: string) { objects.delete(key); },
      async list(options?: { prefix?: string }) {
        const keys = [...objects.keys()].filter((k) => !options?.prefix || k.startsWith(options.prefix));
        return { objects: keys.map((key) => ({ key })), truncated: false };
      },
    } as unknown as R2Bucket,
  };
}

/** In-memory stage storage (the OptionsStageStorage contract). */
function memoryStorage(): OptionsStageStorage & { entries: Map<string, unknown> } {
  const entries = new Map<string, unknown>();
  return {
    entries,
    async put(key: string, value: unknown) { entries.set(key, value); },
    async get<T>(key: string): Promise<T | undefined> {
      const value = entries.get(key);
      return value === null ? undefined : (value as T | undefined);
    },
  };
}

function expiryAtDte(dte: number): ETradeOptionExpireDate {
  const now = new Date();
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + dte));
  return { year: date.getUTCFullYear(), month: date.getUTCMonth() + 1, day: date.getUTCDate() };
}

function makeChain(symbol: string): ETradeOptionChain {
  const expiry = expiryAtDte(30);
  return {
    symbol,
    underlyingPrice: 100,
    selectedExpiry: { year: expiry.year, month: expiry.month, day: expiry.day },
    pairs: [
      {
        call: { symbol, optionType: "CALL", strikePrice: 100, bid: 1.0, ask: 1.2, openInterest: 500, volume: 100 },
        put: { symbol, optionType: "PUT", strikePrice: 100, bid: 1.0, ask: 1.2, openInterest: 500, volume: 100 },
      },
    ],
  } as unknown as ETradeOptionChain;
}

const SCREEN_RESULT = {
  contracts: [],
  scannedAt: "2026-11-15T00:00:00.000Z",
  totalUnderlyingsScanned: 1,
  totalContractsEvaluated: 2,
  matchedCount: 0,
  filterSummary: "AAPL",
};

const CANONICAL_INPUT = {
  reportId: "options-host-manual",
  created: true,
  record: { reportId: "options-host-manual", title: "Options Screen" },
};

function residencyInput(overrides: Partial<ManualOptionsResidencyInput> = {}): ManualOptionsResidencyInput {
  return {
    env: {} as Env,
    storage: memoryStorage(),
    request: { filter: { underlyingSymbols: ["AAPL"] } },
    ...overrides,
  };
}

describe("manual residency delivery (#4450)", () => {
  it("rebuilds shapeReport: generated XLSX/CSV keys are servable through an empty serving store", async () => {
    const fake = fakeR2Bucket();
    const env = { REPORTS_BUCKET: fake.bucket } as unknown as Env;
    const storage = memoryStorage();
    const legCalls: unknown[] = [];
    const canonicalLeg = {
      async store(input: unknown) {
        legCalls.push(input);
        return { reportId: "options-host-manual", created: false };
      },
    };
    const { shapeReport } = createManualOptionsResidencyDelivery(
      residencyInput({ env, storage, canonicalLeg: canonicalLeg as never }),
    );
    const shaped = await shapeReport({ runId: "options-host-manual", userLogin: "tester", screen: { result: SCREEN_RESULT }, canonical: CANONICAL_INPUT } as never);
    expect(shaped.xlsxStatus).toBe("generated");
    expect(shaped.csvStatus).toBe("generated");
    expect(shaped.xlsxKey).toMatch(/^options:xlsx:[0-9a-f]{8}$/);
    expect(shaped.csvKey).toMatch(/^options:csv:[0-9a-f]{8}$/);
    expect(shaped.xlsxUrl).toBe(`/api/options/report.xlsx?key=${encodeURIComponent(shaped.xlsxKey as string)}`);
    expect(shaped.csvUrl).toBe(`/api/options/report.csv?key=${encodeURIComponent(shaped.csvKey as string)}`);
    // The canonical leg re-records the shaped report with its keys.
    expect(legCalls).toHaveLength(1);
    expect((legCalls[0] as { body?: unknown }).body).toMatchObject({ xlsxKey: shaped.xlsxKey, csvKey: shaped.csvKey });
    // Servability: the established endpoints read through getReportPdf
    // against the serving store — which holds NO pointer for a
    // residency write. The direct-R2 fallback must serve the bytes.
    const emptyServingStore = memoryStorage();
    const xlsx = await getReportPdf(env, emptyServingStore, shaped.xlsxKey as string);
    expect(xlsx).not.toBeNull();
    expect(xlsx?.bytes.length).toBeGreaterThan(0);
    const csv = await getReportPdf(env, emptyServingStore, shaped.csvKey as string);
    expect(csv).not.toBeNull();
    expect(new TextDecoder().decode(csv?.bytes ?? new Uint8Array())).toContain("Underlying");
    // The latest keys are written too, so the latest endpoints serve
    // the residency run's reports.
    expect(fake.objects.has("options/latest.xlsx")).toBe(true);
    expect(fake.objects.has("options/latest.csv")).toBe(true);
  });

  it("records XLSX/CSV as failed with a named reason when the blob store is unbound", async () => {
    const legCalls: unknown[] = [];
    const canonicalLeg = {
      async store(input: unknown) {
        legCalls.push(input);
        return { reportId: "options-host-manual", created: false };
      },
    };
    const { shapeReport } = createManualOptionsResidencyDelivery(
      residencyInput({ env: {} as Env, canonicalLeg: canonicalLeg as never }),
    );
    const shaped = await shapeReport({ runId: "options-host-manual", userLogin: "tester", screen: { result: SCREEN_RESULT }, canonical: CANONICAL_INPUT } as never);
    expect(shaped.xlsxStatus).toBe("failed");
    expect(shaped.xlsxError).toMatch(/REPORTS_BUCKET/);
    expect(shaped.csvStatus).toBe("failed");
    expect(shaped.csvError).toMatch(/REPORTS_BUCKET/);
    expect(shaped.xlsxKey).toBeUndefined();
    expect(shaped.csvKey).toBeUndefined();
    expect(shaped.terminal).toBe("partial");
    // The re-record still happens: the failed formats are recorded,
    // not silently dropped.
    expect(legCalls).toHaveLength(1);
    expect((legCalls[0] as { body?: unknown }).body).toMatchObject({ xlsxStatus: "failed", csvStatus: "failed" });
  });

  it("refuses by name at invocation when no environment is bound (the ports still build)", async () => {
    const delivery = createManualOptionsResidencyDelivery(
      residencyInput({ env: undefined }),
    );
    await expect(
      delivery.shapeReport({ runId: "options-host-manual", userLogin: "tester", screen: { result: SCREEN_RESULT }, canonical: CANONICAL_INPUT } as never),
    ).rejects.toThrowError(expect.objectContaining({ code: "stage_port_unavailable" }));
    await expect(
      delivery.deliver({ runId: "options-host-manual", userLogin: "tester", report: { terminal: "completed" } } as never),
    ).rejects.toThrowError(expect.objectContaining({ code: "stage_port_unavailable" }));
  });

  it("deliver honors deferDelivery: no send is attempted and no claim is taken", async () => {
    const claims: Array<[string, string]> = [];
    const suppressor = {
      tryClaim: (runId: string, destination: string) => { claims.push([runId, destination]); return true; },
      wasClaimed: () => false,
      release: () => {},
    };
    const { deliver } = createManualOptionsResidencyDelivery(
      residencyInput({
        request: {
          filter: { underlyingSymbols: ["AAPL"] },
          pushToSlack: true,
          emailTo: "owner@example.test",
          deferDelivery: true,
        },
        suppressor: suppressor as never,
      }),
    );
    const delivered = await deliver({ runId: "options-host-manual", userLogin: "tester", report: { terminal: "completed" } } as never);
    expect(delivered.terminal).toBe("completed");
    expect(delivered.deliveryState).toBe("delivered");
    expect(delivered.slackState).toBeUndefined();
    expect(delivered.emailState).toBeUndefined();
    expect(claims).toEqual([]);
  });

  it("deliver re-fetches attachment bytes through the blob store before sending", async () => {
    const fake = fakeR2Bucket();
    const env = { REPORTS_BUCKET: fake.bucket } as unknown as Env;
    const storage = memoryStorage();
    const { shapeReport, deliver } = createManualOptionsResidencyDelivery(
      residencyInput({
        env,
        storage,
        request: { filter: { underlyingSymbols: ["AAPL"] }, pushToSlack: true },
      }),
    );
    const shaped = await shapeReport({ runId: "options-host-manual", userLogin: "tester", screen: { result: SCREEN_RESULT }, canonical: CANONICAL_INPUT } as never);
    fake.gets.length = 0;
    const delivered = await deliver({ runId: "options-host-manual", userLogin: "tester", report: shaped } as never);
    // No gate/binding in the test env: the send fails, but only after
    // the attachment bytes were re-fetched through the blob store.
    expect(delivered.slackState).toBe("failed");
    expect(fake.gets).toContain(`options/xlsx/${(shaped.xlsxKey as string).slice("options:xlsx:".length)}`);
    expect(fake.gets).toContain(`options/csv/${(shaped.csvKey as string).slice("options:csv:".length)}`);
  });
});

describe("manual route gate (#4450)", () => {
  const configuredEnv = {
    AGENT_DB: {},
    JOB_PIPELINE_WORKFLOW: { create: async () => ({}) },
  } as unknown as Env;
  const symbolsFilter = { underlyingSymbols: ["AAPL"] };
  const discoveryFilter = { universe: "nasdaq100" };

  it("routes a symbol-scoped, residency-bound-broker screen through the host", () => {
    const decision = manualScreenDispatchRoute({
      broker: "etrade" as BrokerId,
      filter: symbolsFilter,
      env: configuredEnv,
    });
    expect(decision.route).toBe("host");
  });

  it("keeps a non-residency broker on the sync dispatch (#3960)", () => {
    for (const broker of ["alpaca", "public"] as BrokerId[]) {
      const decision = manualScreenDispatchRoute({ broker, filter: symbolsFilter, env: configuredEnv });
      expect(decision.route).toBe("sync");
      expect(decision.reason).toMatch(/#3960/);
    }
  });

  it("keeps a discovery-mode screen on the sync dispatch (#4473)", () => {
    for (const filter of [discoveryFilter, { underlyingSymbols: [] }, { underlyingSymbols: ["  "] }]) {
      const decision = manualScreenDispatchRoute({
        broker: "etrade" as BrokerId,
        filter: filter as never,
        env: configuredEnv,
      });
      expect(decision.route).toBe("sync");
      expect(decision.reason).toMatch(/#4473/);
    }
  });

  it("keeps the sync dispatch when the residency bindings are not configured", () => {
    const noDb = { JOB_PIPELINE_WORKFLOW: { create: async () => ({}) } } as unknown as Env;
    expect(manualScreenDispatchRoute({ broker: "etrade" as BrokerId, filter: symbolsFilter, env: noDb }).route).toBe("sync");
    const noWorkflow = { AGENT_DB: {} } as unknown as Env;
    expect(manualScreenDispatchRoute({ broker: "etrade" as BrokerId, filter: symbolsFilter, env: noWorkflow }).route).toBe("sync");
    const noCreate = { AGENT_DB: {}, JOB_PIPELINE_WORKFLOW: {} } as unknown as Env;
    expect(manualScreenDispatchRoute({ broker: "etrade" as BrokerId, filter: symbolsFilter, env: noCreate }).route).toBe("sync");
  });

  it("the shared response body carries the result plus the report keys", () => {
    const body = manualScreenResponseBody(
      { runId: "r1", state: "completed" },
      { pdfKey: "options:pdf:aa", reportUrl: "/pdf", xlsxKey: "options:xlsx:bb", xlsxUrl: "/xlsx", csvKey: "options:csv:cc", csvUrl: "/csv" },
    );
    expect(body).toEqual({
      runId: "r1",
      state: "completed",
      pdfKey: "options:pdf:aa",
      reportUrl: "/pdf",
      xlsxKey: "options:xlsx:bb",
      xlsxUrl: "/xlsx",
      csvKey: "options:csv:cc",
      csvUrl: "/csv",
    });
  });
});

describe("manual-shape run through the host (#4450)", () => {
  it("the shared guard passes manual shapeReport/deliver (comparison still refuses)", () => {
    expect(() => assertOptionsStageRebuildable("manual", "shapeReport", "r1")).not.toThrow();
    expect(() => assertOptionsStageRebuildable("manual", "deliver", "r1")).not.toThrow();
    expect(() => assertOptionsStageRebuildable("comparison", "deliver", "r1")).toThrowError(
      expect.objectContaining({ code: "stage_port_unavailable" }),
    );
    expect(() => assertOptionsStageRebuildable("comparison", "shapeReport", "r1")).toThrowError(
      OptionsStepPortsError,
    );
  });

  it("optionsWorkflowRunDepsFromEnv refuses by name when the durable store is unbound", () => {
    expect(() => optionsWorkflowRunDepsFromEnv({} as Env)).toThrow(
      "job_pipeline_workflow_not_configured",
    );
  });

  it("completes all eight stages through the host, with the report artifact readable from the durable store", async () => {
    const fake = fakeR2Bucket();
    const env = { REPORTS_BUCKET: fake.bucket } as unknown as Env;
    const stores: JobPipelineStores = createInMemoryJobPipelineStores();
    const recordStore = new InMemoryJobRunRecordStore();
    const runRecorder = jobRunRecorderFromStore(recordStore);
    const created: Array<{ id: string; params: unknown }> = [];
    const runId = "options-host-4450-manual";
    const request = {
      assetClass: "options",
      runIdentity: { runId },
      trigger: "manual",
      classInput: { request: { filter: { underlyingSymbols: ["AAPL"] } } },
    };
    await startOptionsScreenWorkflow(env, {
      runId,
      request,
      userLogin: "OpenAIMP",
      trigger: "manual",
    }, {
      stores,
      runRecorder,
      startWorkflow: (async (id: string, params: unknown) => {
        created.push({ id, params });
        return { instanceId: "wf-4450" };
      }) as never,
    });
    expect(created).toHaveLength(1);
    expect(created[0].id).toBe(optionsScreenJobId(runId));

    DynamicOptionsScreener.setTestChainsFixture({ AAPL: makeChain("AAPL") });
    try {
      const stepDeps: OptionsWorkflowStepDeps = {
        definitions: stores.definitions,
        artifacts: stores.artifacts,
        env,
        chainSourceFor: () => undefined,
      };
      const registry = registerOptionsWorkflowSteps(createBuiltinStepRegistry(), stepDeps);
      const deps: JobPipelineDeps = {
        stores,
        runRecorder,
        publisher: null,
        steps: registry,
        invocation: "workflow-shard",
      };
      const journal = {
        step: {
          do: async <T>(_name: string, fn: () => Promise<T>): Promise<T> => fn(),
        },
      };
      const outcome = await runJobPipelineWorkflowFlow(deps, journal.step as never, {
        jobId: optionsScreenJobId(runId),
        trigger: "manual",
      });
      expect(outcome.state).toBe("completed");
      const view = await readOptionsWorkflowRun({ stores, runRecorder }, optionsScreenJobId(runId));
      expect(view.state).toBe("completed");
      expect(view.stages.map((stage) => stage.stageId)).toEqual([...OPTIONS_PIPELINE_STAGES]);
      expect(view.stages.every((stage) => stage.status === "completed")).toBe(true);
      // The report artifact is readable from the durable store. The
      // stored artifact wraps the flat report as {terminal, report}
      // (the shape the manual route reads back).
      expect(view.shapeReport).toBeDefined();
      const shapedReport = (view.shapeReport as { report?: { xlsxStatus?: string; csvStatus?: string } })?.report;
      expect(shapedReport?.xlsxStatus).toBe("generated");
      expect(shapedReport?.csvStatus).toBe("generated");
      // The screen artifact is readable too, through the same adapter
      // the route uses after awaiting settlement.
      const stageStorage = optionsStageStorageFromArtifacts(stores.artifacts, view.engineRunId);
      const screen = await stageStorage.get<{ result?: { matchedCount?: number } }>(`options:${runId}:screen`);
      expect(screen?.result).toBeDefined();
    } finally {
      DynamicOptionsScreener.clearTestChainsFixture();
    }
  });
});
